function Avatar({ person, size = 'md' }) {
  const data = typeof person === 'string' ? people.find((item) => item.name === person) || { initials: person.slice(0, 2), color: 'slate' } : person;
  return <span className={`avatar avatar-${size} avatar-${data.color || 'mint'}`}>{data.initials}</span>;
}

function StatusPill({ children, tone = 'gray', dot = false }) {
  return <span className={`status-pill status-${tone}`}>{dot && <span className="status-dot" />}{children}</span>;
}

function Button({ children, variant = 'primary', icon: Icon, onClick, className = '', type = 'button' }) {
  return <button type={type} className={`button button-${variant} ${className}`} onClick={onClick}>{Icon && <Icon size={16} strokeWidth={2} />}{children}</button>;
}

function LegacyWorkspaceShell() {
  const [activeView, setActiveView] = useState('dashboard');
  const [tasks, setTasks] = useState(seedTasks);
  const [checkedIn, setCheckedIn] = useState(true);
  const [showCreateTask, setShowCreateTask] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [toast, setToast] = useState(null);

  const notify = (message, tone = 'success') => {
    setToast({ message, tone });
    window.setTimeout(() => setToast(null), 3200);
  };

  const taskStats = useMemo(() => ({
    open: tasks.filter((task) => !['Completed', 'Archived'].includes(task.status)).length,
    review: tasks.filter((task) => task.status === 'Under Review').length,
    blocked: tasks.filter((task) => task.status === 'Blocked').length,
  }), [tasks]);

  const cycleTask = (id) => {
    const order = ['Assigned', 'In Progress', 'Under Review', 'Completed'];
    setTasks((current) => current.map((task) => {
      if (task.id !== id) return task;
      const next = order[(order.indexOf(task.status) + 1) % order.length];
      return { ...task, status: next, progress: next === 'Completed' ? 100 : Math.min(task.progress + 18, 92) };
    }));
    notify('Task status updated');
  };

  const createTask = (event) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const title = form.get('title');
    if (!title) return;
    setTasks((current) => [{ id: `DG-${112 + current.length}`, title, description: form.get('description') || 'New workspace task', status: 'Assigned', priority: form.get('priority'), due: 'Oct 02', assignee: form.get('assignee'), team: 'Leadership', type: 'Operations', progress: 0 }, ...current]);
    setShowCreateTask(false);
    notify('Task created and added to the workspace');
  };

  const viewTitles = {
    dashboard: ['Dashboard', 'Your operating view for today'], tasks: ['Tasks', 'Keep work moving with context'], projects: ['Projects', 'Milestones, resources and delivery'], teams: ['Teams', 'People grouped around outcomes'], chat: ['Chat', 'Keep conversations close to the work'], training: ['Training', 'Build capability in the flow of work'], documents: ['Documents', 'A permission-aware knowledge library'], calendar: ['Calendar', 'A shared view of important moments'], employees: ['Employees', 'People, roles and workspace access'], reports: ['Reports', 'Transparent signals for better decisions'], recruitment: ['Recruitment', 'Open roles and the hiring pipeline'], admin: ['Admin center', 'Configure roles, permissions and governance'], settings: ['Settings', 'Workspace policies and security controls']
  };

  return <div className="app-shell">
    <Sidebar activeView={activeView} setActiveView={setActiveView} />
    <main className="main-content">
      <Topbar activeView={activeView} setActiveView={setActiveView} showProfileMenu={showProfileMenu} setShowProfileMenu={setShowProfileMenu} notify={notify} />
      <div className="page-wrap">
        {activeView !== 'dashboard' && <PageIntro title={viewTitles[activeView][0]} subtitle={viewTitles[activeView][1]} activeView={activeView} onCreate={() => activeView === 'tasks' ? setShowCreateTask(true) : notify('Workspace action ready to configure')} />}
        {activeView === 'dashboard' && <Dashboard checkedIn={checkedIn} setCheckedIn={setCheckedIn} setActiveView={setActiveView} taskStats={taskStats} tasks={tasks} cycleTask={cycleTask} notify={notify} />}
        {activeView === 'tasks' && <TasksView tasks={tasks} cycleTask={cycleTask} onCreate={() => setShowCreateTask(true)} />}
        {activeView === 'projects' && <ProjectsView notify={notify} />}
        {activeView === 'teams' && <TeamsView setActiveView={setActiveView} />}
        {activeView === 'chat' && <ChatView notify={notify} />}
        {activeView === 'training' && <TrainingView notify={notify} />}
        {activeView === 'documents' && <DocumentsView notify={notify} />}
        {activeView === 'calendar' && <CalendarView />}
        {activeView === 'employees' && <EmployeesView notify={notify} />}
        {activeView === 'reports' && <ReportsView />}
        {activeView === 'recruitment' && <RecruitmentView notify={notify} />}
        {activeView === 'admin' && <AdminView notify={notify} />}
        {activeView === 'settings' && <SettingsView />}
      </div>
    </main>
    {showCreateTask && <CreateTaskModal onClose={() => setShowCreateTask(false)} onSubmit={createTask} />}
    {toast && <div className={`toast toast-${toast.tone}`}><CheckCircle2 size={17} />{toast.message}<button onClick={() => setToast(null)}><X size={14} /></button></div>}
  </div>;
}

function Sidebar({ activeView, setActiveView }) {
  return <aside className="sidebar">
    <div className="brand-row"><div className="brand-mark">D</div><div><div className="brand-name">dialgrow</div><div className="brand-subtitle">workspace</div></div><button className="sidebar-collapse" aria-label="Collapse sidebar"><ChevronRight size={15} /></button></div>
    <div className="workspace-switcher"><span className="workspace-icon"><Command size={15} /></span><div><strong>DialGrow HQ</strong><span>Internal workspace</span></div><ChevronDown size={15} /></div>
    <nav className="sidebar-nav">
      {navGroups.map((group) => <div className="nav-group" key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(({ id, label, icon: Icon, count }) => <button key={id} onClick={() => setActiveView(id)} className={`nav-item ${activeView === id ? 'nav-active' : ''}`}><Icon size={17} strokeWidth={activeView === id ? 2.2 : 1.8} /><span>{label}</span>{count && <span className="nav-count">{count}</span>}</button>)}</div>)}
    </nav>
    <div className="sidebar-bottom"><button className="nav-item" onClick={() => setActiveView('settings')}><Settings2 size={17} /><span>Settings</span></button><div className="sync-card"><div className="sync-icon"><Zap size={15} /></div><div><strong>Workspace live</strong><span>Supabase connected</span></div><span className={`live-dot ${hasSupabaseConfig ? 'live' : ''}`} /></div><div className="profile-mini"><Avatar person={people[0]} size="sm" /><div><strong>Durga Prashad</strong><span>Main Admin</span></div><MoreHorizontal size={16} /></div></div>
  </aside>;
}

function Topbar({ activeView, setActiveView, showProfileMenu, setShowProfileMenu, notify }) {
  return <header className="topbar"><div className="mobile-brand"><div className="brand-mark">D</div><span>dialgrow</span></div><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={14} /><strong>{activeView === 'dashboard' ? 'Overview' : activeView.charAt(0).toUpperCase() + activeView.slice(1)}</strong></div><div className="topbar-actions"><label className="search-box"><Search size={16} /><input placeholder="Search workspace" /><kbd>⌘ K</kbd></label><button className="icon-button" title="AI assistant" onClick={() => notify('AI workspace is ready for your task context')}><Bot size={18} /></button><button className="icon-button notification-button" title="Notifications" onClick={() => notify('You have 3 new notifications')}><Bell size={18} /><span /></button><button className="top-profile" onClick={() => setShowProfileMenu((value) => !value)}><Avatar person={people[0]} size="sm" /><ChevronDown size={14} /></button>{showProfileMenu && <div className="profile-menu"><div className="profile-menu-head"><Avatar person={people[0]} /><div><strong>Business Admin</strong><span>business@dialgrow.com</span></div></div><button onClick={() => setActiveView('employees')}><Users size={15} />My profile</button><button onClick={() => notify('Session is already secure')}><LockKeyhole size={15} />Security</button><button onClick={() => notify('Signed out of the workspace', 'info')}><X size={15} />Sign out</button></div>}</div></header>;
}

function PageIntro({ title, subtitle, activeView, onCreate }) {
  return <div className="page-intro"><div><div className="eyebrow">Workspace / {title}</div><h1>{title}</h1><p>{subtitle}</p></div><div className="intro-actions"><button className="filter-button"><Filter size={15} /> Filters <ChevronDown size={14} /></button>{['tasks', 'projects', 'teams', 'documents', 'training', 'recruitment'].includes(activeView) && <Button icon={Plus} onClick={onCreate}>{activeView === 'tasks' ? 'Create task' : `Add ${activeView.slice(0, -1)}`}</Button>}</div></div>;
}

function Dashboard({ checkedIn, setCheckedIn, setActiveView, taskStats, tasks, cycleTask, notify }) {
  const todayTasks = tasks.filter((task) => ['Today', 'Tomorrow'].includes(task.due)).slice(0, 4);
  return <>
    <section className="welcome-row"><div><div className="eyebrow">Monday, September 28, 2026</div><h1>Good morning, Durga <span className="wave">✦</span></h1><p>Here’s the pulse of DialGrow today. Keep the important work moving.</p></div><div className="welcome-actions"><div className={`checkin-control ${checkedIn ? 'checkin-on' : ''}`}><span className="checkin-status"><span className="status-dot" />{checkedIn ? 'Working now' : 'Not checked in'}</span><button onClick={() => { setCheckedIn(!checkedIn); notify(checkedIn ? 'You have checked out' : 'You are checked in'); }}>{checkedIn ? 'Check out' : 'Check in'}</button></div><button className="icon-button subtle" onClick={() => notify('Invite link copied')} title="Invite teammate"><Users size={17} /></button></div></section>
    <section className="dashboard-hero"><div className="hero-copy"><div className="hero-kicker"><span className="live-dot live" /> LIVE WORKSPACE</div><h2>Your operating loop, in one place.</h2><p>From first task to final review, keep context close to the work and make progress visible.</p><div className="hero-links"><button onClick={() => setActiveView('tasks')}>Open my tasks <ArrowUpRight size={15} /></button><button onClick={() => setActiveView('training')}>Continue learning <ChevronRight size={15} /></button></div></div><div className="hero-orbit"><div className="orbit-ring ring-one" /><div className="orbit-ring ring-two" /><div className="orbit-core"><Sparkles size={24} /><span>AI</span></div><span className="orbit-node node-one"><Target size={15} /></span><span className="orbit-node node-two"><MessageSquare size={15} /></span><span className="orbit-node node-three"><Check size={15} /></span></div></section>
    <section className="metric-grid"><MetricCard label="Open tasks" value={taskStats.open} detail="2 due today" icon={ListTodo} tone="mint" trend="12%" trendUp /><MetricCard label="Review queue" value={taskStats.review} detail="Needs your attention" icon={ClipboardCheck} tone="blue" trend="3" /><MetricCard label="Blocked work" value={taskStats.blocked} detail="1 needs an update" icon={Clock3} tone="orange" trend="1" /><MetricCard label="Learning progress" value="76%" detail="On track this week" icon={GraduationCap} tone="violet" trend="8%" trendUp /></section>
    <section className="dashboard-grid"><div className="surface-card task-focus"><CardHeader title="Today’s focus" action="View all tasks" onAction={() => setActiveView('tasks')} /><div className="task-list">{todayTasks.map((task) => <TaskRow task={task} key={task.id} onStatus={() => cycleTask(task.id)} />)}</div><button className="add-row" onClick={() => setActiveView('tasks')}><Plus size={15} /> Add a task to today</button></div><div className="surface-card activity-card"><CardHeader title="Workspace activity" action="See all" onAction={() => setActiveView('chat')} /><div className="activity-list"><ActivityItem avatar="Meera Nair" color="violet" text="submitted a review on" highlight="Review outbound playbook" time="8 min ago" /><ActivityItem avatar="Arjun Kapoor" color="orange" text="moved" highlight="Ship API handoff" time="24 min ago" /><ActivityItem avatar="Sana Iqbal" color="blue" text="checked in for the day" time="42 min ago" /><ActivityItem avatar="DialGrow AI" color="mint" bot text="prepared a brief for" highlight="Onboarding journey" time="1 hr ago" /></div></div></section>
    <section className="lower-grid"><div className="surface-card team-card"><CardHeader title="Your teams" action="Manage teams" onAction={() => setActiveView('teams')} /><div className="team-list"><TeamRow name="Leadership" members="4 people" color="mint" progress={84} /><TeamRow name="Growth" members="8 people" color="violet" progress={67} /><TeamRow name="Engineering" members="6 people" color="orange" progress={52} /></div></div><div className="surface-card announcement-card"><div className="announcement-label"><span className="announcement-icon"><MegaphoneIcon /></span><span>Announcement</span><span className="announcement-date">Today</span></div><h3>Q4 operating rhythm is live</h3><p>New weekly reviews and learning tracks are ready for every team. Start with your role dashboard.</p><button className="text-button" onClick={() => setActiveView('training')}>Read announcement <ArrowUpRight size={15} /></button></div></section>
  </>;
}

function MetricCard({ label, value, detail, icon: Icon, tone, trend, trendUp }) { return <div className="metric-card"><div className={`metric-icon metric-${tone}`}><Icon size={18} /></div><div className="metric-data"><span>{label}</span><strong>{value}</strong><small>{detail}</small></div><span className={`metric-trend ${trendUp ? 'trend-up' : ''}`}>{trendUp ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{trend}</span></div>; }
function CardHeader({ title, action, onAction }) { return <div className="card-header"><h3>{title}</h3>{action && <button className="text-button muted" onClick={onAction}>{action}<ChevronRight size={14} /></button>}</div>; }
function TaskRow({ task, onStatus }) { return <div className="task-row"><button className={`task-check ${task.status === 'Completed' ? 'task-done' : ''}`} onClick={onStatus} aria-label="Update task status">{task.status === 'Completed' && <Check size={13} />}</button><div className="task-row-copy"><strong>{task.title}</strong><span>{task.id} <span className="separator">•</span> {task.team}</span></div><StatusPill tone={statusTone[task.status]} dot>{task.status === 'In Progress' ? 'IN PROGRESS' : task.status.toUpperCase()}</StatusPill><span className={`priority priority-${priorityTone[task.priority]}`}>{task.priority}</span><span className="due-date">{task.due}</span></div>; }
function ActivityItem({ avatar, text, highlight, time, color, bot }) { return <div className="activity-item"><span className={`activity-avatar ${color}`}>{bot ? <Bot size={14} /> : <Avatar person={avatar} size="xs" />}</span><p><strong>{bot ? 'DialGrow AI' : avatar}</strong> {text} {highlight && <b>{highlight}</b>}<span>{time}</span></p></div>; }
function TeamRow({ name, members, color, progress }) { return <div className="team-row"><span className={`team-dot ${color}`} /><div><strong>{name}</strong><span>{members}</span></div><div className="progress-bar"><span style={{ width: `${progress}%` }} /></div><b>{progress}%</b><ChevronRight size={15} /></div>; }
function MegaphoneIcon() { return <span className="mini-megaphone">!</span>; }

function TasksView({ tasks, cycleTask, onCreate }) {
  const columns = ['Assigned', 'In Progress', 'Under Review', 'Completed'];
  return <section className="tasks-view"><div className="view-toolbar"><div className="segmented"><button className="selected"><LayoutDashboard size={15} /> Board</button><button><ListTodo size={15} /> List</button><button><CalendarDays size={15} /> Calendar</button></div><div className="toolbar-right"><span className="toolbar-note"><span className="live-dot live" /> Synced just now</span><button className="icon-button" title="Filter tasks"><Filter size={17} /></button><Button icon={Plus} onClick={onCreate}>Create task</Button></div></div><div className="task-board">{columns.map((column) => <div className="task-column" key={column}><div className="column-head"><div><span className={`column-dot column-${statusTone[column] || 'gray'}`} /><strong>{column}</strong><span>{tasks.filter((task) => task.status === column).length}</span></div><button><MoreHorizontal size={16} /></button></div><div className="column-cards">{tasks.filter((task) => task.status === column).map((task) => <TaskCard key={task.id} task={task} onStatus={() => cycleTask(task.id)} />)}{column === 'Assigned' && <button className="column-add" onClick={onCreate}><Plus size={15} /> Add task</button>}</div></div>)}</div></section>;
}
function TaskCard({ task, onStatus }) { return <article className="task-card"><div className="task-card-top"><span className="task-id">{task.id}</span><button><MoreHorizontal size={15} /></button></div><h3>{task.title}</h3><p>{task.description}</p><div className="task-card-meta"><StatusPill tone={priorityTone[task.priority]}>{task.priority}</StatusPill><span><Clock3 size={13} />{task.due}</span><span><Link2 size={13} />{task.type}</span></div><div className="task-card-bottom"><div className="assignee"><Avatar person={task.assignee} size="xs" /><span>{task.assignee.split(' ')[0]}</span></div><button className="progress-ring" onClick={onStatus} title="Advance task status"><span style={{ '--progress': `${task.progress * 3.6}deg` }}>{task.progress}%</span></button></div></article>; }

function ProjectsView({ notify }) { const projects = [{ name: 'Workspace foundation', owner: 'Durga Prashad', progress: 78, status: 'On track', color: 'mint', due: 'Oct 04' }, { name: 'Q4 growth motion', owner: 'Meera Nair', progress: 54, status: 'At risk', color: 'violet', due: 'Oct 12' }, { name: 'Technical onboarding', owner: 'Arjun Kapoor', progress: 41, status: 'On track', color: 'orange', due: 'Oct 18' }]; return <section className="section-stack"><div className="surface-card"><CardHeader title="Active projects" action="Project settings" onAction={() => notify('Project settings ready to configure')} /><div className="project-table"><div className="table-head"><span>Project</span><span>Owner</span><span>Progress</span><span>Status</span><span>Due</span></div>{projects.map((project) => <div className="project-row" key={project.name}><div className="project-name"><span className={`project-mark ${project.color}`}><FolderKanban size={16} /></span><div><strong>{project.name}</strong><span>Shared workspace project</span></div></div><div className="table-person"><Avatar person={project.owner} size="xs" />{project.owner.split(' ')[0]}</div><div className="project-progress"><div className="progress-bar"><span style={{ width: `${project.progress}%` }} /></div><b>{project.progress}%</b></div><StatusPill tone={project.status === 'At risk' ? 'amber' : 'green'} dot>{project.status.toUpperCase()}</StatusPill><span className="project-due">{project.due}</span></div>)}</div></div><div className="split-grid"><div className="surface-card"><CardHeader title="Project signals" /><div className="signal-list"><SignalRow icon={ArrowUpRight} label="Delivery velocity" value="+18%" caption="vs last month" tone="green" /><SignalRow icon={Clock3} label="Review time" value="1.8d" caption="average turnaround" tone="blue" /><SignalRow icon={Target} label="Milestones" value="12 / 16" caption="completed this quarter" tone="orange" /></div></div><div className="surface-card empty-insight"><div className="empty-icon"><Sparkles size={20} /></div><h3>Project intelligence</h3><p>AI summaries will appear here when your workspace has enough project activity to spot patterns.</p><Button variant="secondary" icon={Bot} onClick={() => notify('Project intelligence is available in the AI workspace')}>Ask DialGrow AI</Button></div></div></section>; }
function SignalRow({ icon: Icon, label, value, caption, tone }) { return <div className="signal-row"><span className={`signal-icon ${tone}`}><Icon size={16} /></span><div><strong>{label}</strong><span>{caption}</span></div><b>{value}</b></div>; }

